import heapq

def match(orders):
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    active = {}     # id -> {'side','price','qty','seq'}
    trades = []
    seq_counter = 0

    def match_incoming(side, price, qty, is_market, incoming_id):
        nonlocal seq_counter
        if side == 'buy':
            book = sell_heap
        else:
            book = buy_heap

        while qty > 0 and book:
            top = book[0]
            oid = top[-1]
            if oid not in active or active[oid]['qty'] <= 0:
                heapq.heappop(book)
                continue
            order = active[oid]
            if not is_market:
                if side == 'buy' and order['price'] > price:
                    break
                if side == 'sell' and order['price'] < price:
                    break
            trade_qty = min(qty, order['qty'])
            trade_price = order['price']
            if side == 'buy':
                trades.append([incoming_id, oid, trade_price, trade_qty])
            else:
                trades.append([oid, incoming_id, trade_price, trade_qty])
            qty -= trade_qty
            order['qty'] -= trade_qty
            if order['qty'] == 0:
                heapq.heappop(book)
                del active[oid]
        return qty

    for o in orders:
        typ = o[0]
        if typ == 'limit':
            _, oid, side, price, qty = o
            remaining = match_incoming(side, price, qty, False, oid)
            if remaining > 0:
                active[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
                seq_counter += 1
            else:
                seq_counter += 1
        elif typ == 'ioc':
            _, oid, side, price, qty = o
            match_incoming(side, price, qty, False, oid)
            seq_counter += 1
        elif typ == 'market':
            _, oid, side, qty = o
            match_incoming(side, 0, qty, True, oid)
            seq_counter += 1
        elif typ == 'cancel':
            _, oid = o
            if oid in active:
                del active[oid]
            seq_counter += 1

    return trades

